/** Boxes one fragment around the participants and message rows its regions reference. */
export function sequenceFragmentBox(
    fragment: DiagramSequenceFragment,
    edges: PositionedDiagramEdge[],
    nodesById: Map<string, PositionedDiagramNode>,
): PositionedSequenceFragment {
    const members = fragmentEdges(fragment, edges)
    const participantIds = new Set(members.flatMap(({ from, to }) => [from, to]))
    const participantCenters = [...participantIds].map((id) => nodeCenter(nodesById.get(id) as PositionedDiagramNode).x)
    const rows = members.map(({ points }) => points[0].y)
    const x = snap(Math.min(...participantCenters) - 16)
    const y = snap(Math.min(...rows) - 32)
    const right = snap(Math.max(...participantCenters) + 16)
    const bottom = snap(Math.max(...rows) + 24)
    const guardPositions = fragment.regions.map(({ edgeIds, guard }) => {
        const firstRow = Math.min(...edges.filter(({ id }) => edgeIds.includes(id)).map(({ points }) => points[0].y))

        return { guard, y: snap(firstRow - 12) }
    })

    return {
        ...(fragment.regions.length === 2 ? { dividerY: snap(guardPositions[1].y - 12) } : {}),
        guardPositions, height: bottom - y, id: fragment.id, operator: fragment.operator, width: right - x, x, y,
    }
}

function layoutSequenceFragments(
    fragments: DiagramSequenceFragment[],
    edges: PositionedDiagramEdge[],
    nodes: PositionedDiagramNode[],
) {
    const nodesById = new Map(nodes.map((node) => [node.id, node]))

    return fragments.map((fragment) => sequenceFragmentBox(fragment, edges, nodesById))
}

/** Measures the surface from already-positioned objects. It reads cached geometry only; it never routes or lays out. */
export function surfaceSize(
    nodes: PositionedDiagramNode[],
    edges: PositionedDiagramEdge[],
    groups: PositionedDiagramGroup[],
    fragments: PositionedSequenceFragment[] = [],
    activations: PositionedSequenceActivation[] = [],
) {
    const horizontalValues = [
        ...nodes.map(({ width, x }) => x + width),
        ...edges.flatMap(({ labelPlacement, points }) => [
            ...points.map(({ x }) => x), ...(labelPlacement ? [labelPlacement.x + labelPlacement.width] : []),
        ]),
        ...groups.map(({ width, x }) => x + width),
        ...fragments.map(({ width, x }) => x + width),
        ...activations.map(({ width, x }) => x + width),
    ]
    const verticalValues = [
        ...nodes.map(({ height, y }) => y + height),
        ...edges.flatMap(({ labelPlacement, points }) => [
            ...points.map(({ y }) => y), ...(labelPlacement ? [labelPlacement.y + labelPlacement.height] : []),
        ]),
        ...groups.map(({ height, y }) => y + height),
        ...fragments.map(({ height, y }) => y + height),
        ...activations.map(({ height, y }) => y + height),
    ]

    return {
        height: snap(Math.max(SURFACE_PADDING, ...verticalValues) + SURFACE_PADDING),
        width: snap(Math.max(SURFACE_PADDING, ...horizontalValues) + SURFACE_PADDING),
    }
}

/** Fill missing diagram geometry while preserving every supplied coordinate, size, and waypoint. */
export function layout(data: DiagramData): PositionedDiagramData {
    const nodes = data.meta.type === 'sequence' ? layoutSequenceNodes(data) : layoutLayeredNodes(data)
    const edges = layoutEdges(data, nodes)
    const groups = layoutGroups(data.groups, nodes)
    const initialSize = surfaceSize(nodes, edges, groups)
    const activations = data.meta.type === 'sequence' ? layoutSequenceActivations(edges, nodes, initialSize.height - 24) : []
    const fragments = data.meta.type === 'sequence' ? layoutSequenceFragments(data.fragments ?? [], edges, nodes) : []
    const { height, width } = surfaceSize(nodes, edges, groups, fragments, activations)

    return { ...data, activations, edges, fragments, groups, height, nodes, width }
}

import { useCallback, useSyncExternalStore } from 'react'
import {
    diagramGeometryService,
    type DiagramGeometryService,
    type DiagramSurfaceSize,
    type PositionedBoxField,
    type PositionedFragmentField,
    type PositionedNodeField,
} from '../../services/diagrams/diagram_geometry_service'

function useGeometrySnapshot<Value>(
    subscribeScoped: (listener: () => void) => () => void,
    getSnapshot: () => Value,
    service: DiagramGeometryService,
) {
    const subscribe = useCallback((listener: () => void) => {
        const unsubscribeScoped = subscribeScoped(listener)
        const unsubscribeSession = service.subscribeGeometrySession(listener)

        return () => {
            unsubscribeScoped()
            unsubscribeSession()
        }
    }, [service, subscribeScoped])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Subscribes one leaf to one derived geometry field of one node. */
export function useDiagramNodeGeometryField(
    nodeId: string,
    field: PositionedNodeField,
    service: DiagramGeometryService = diagramGeometryService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeNodeGeometryField(nodeId, field, listener),
        [field, nodeId, service],
    )
    const getSnapshot = useCallback(() => service.getNodeGeometryFieldSnapshot(nodeId, field), [field, nodeId, service])

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one edge leaf to its own route; the array reference changes only when the route changes. */
export function useDiagramEdgeRoute(edgeId: string, service: DiagramGeometryService = diagramGeometryService) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeEdgeGeometryField(edgeId, 'points', listener),
        [edgeId, service],
    )
    const getSnapshot = useCallback(() => service.getEdgeRouteSnapshot(edgeId), [edgeId, service])

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one edge label leaf to its own placement box. */
export function useDiagramEdgeLabelPlacement(edgeId: string, service: DiagramGeometryService = diagramGeometryService) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeEdgeGeometryField(edgeId, 'labelPlacement', listener),
        [edgeId, service],
    )
    const getSnapshot = useCallback(() => service.getEdgeLabelPlacementSnapshot(edgeId), [edgeId, service])

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one derived geometry field of one group. */
export function useDiagramGroupGeometryField(
    groupId: string,
    field: PositionedBoxField,
    service: DiagramGeometryService = diagramGeometryService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeGroupGeometryField(groupId, field, listener),
        [field, groupId, service],
    )
    const getSnapshot = useCallback(() => service.getGroupGeometryFieldSnapshot(groupId, field), [field, groupId, service])

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one derived geometry field of one sequence activation bar. */
export function useDiagramActivationField(
    activationId: string,
    field: PositionedBoxField,
    service: DiagramGeometryService = diagramGeometryService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeActivationField(activationId, field, listener),
        [activationId, field, service],
    )
    const getSnapshot = useCallback(
        () => service.getActivationFieldSnapshot(activationId, field),
        [activationId, field, service],
    )

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one derived geometry field of one sequence fragment box. */
export function useDiagramFragmentGeometryField(
    fragmentId: string,
    field: PositionedFragmentField,
    service: DiagramGeometryService = diagramGeometryService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeFragmentGeometryField(fragmentId, field, listener),
        [field, fragmentId, service],
    )
    const getSnapshot = useCallback(
        () => (field === 'guardPositions'
            ? service.getFragmentGuardPositionsSnapshot(fragmentId)
            : service.getFragmentGeometryFieldSnapshot(fragmentId, field as PositionedBoxField)),
        [field, fragmentId, service],
    )

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

/** Subscribes the activation collection host to activation membership only. */
export function useDiagramActivationIds(service: DiagramGeometryService = diagramGeometryService) {
    return useGeometrySnapshot(service.subscribeActivationIds, service.getActivationIdsSnapshot, service)
}

/** Subscribes the fragment collection host to fragment membership only. */
export function useDiagramFragmentIds(service: DiagramGeometryService = diagramGeometryService) {
    return useGeometrySnapshot(service.subscribeFragmentIds, service.getFragmentIdsSnapshot, service)
}

/** Subscribes the surface leaf to one surface bound, which changes only when that bound actually changes. */
export function useDiagramSurfaceField(
    field: keyof DiagramSurfaceSize,
    service: DiagramGeometryService = diagramGeometryService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeSurfaceField(field, listener),
        [field, service],
    )
    const getSnapshot = useCallback(() => service.getSurfaceFieldSnapshot(field), [field, service])

    return useGeometrySnapshot(subscribe, getSnapshot, service)
}

import { Box, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material'
import { useCallback, useSyncExternalStore, type ReactNode, type SyntheticEvent } from 'react'
import {
    diagramComparisonLayoutService, type DiagramComparisonLayoutService, type DiagramComparisonMode,
} from './diagram_comparison_layout_service'

interface DiagramComparisonLayoutProps {
    horizontalComparison: ReactNode
    layoutService?: DiagramComparisonLayoutService
    tabbedComparison: ReactNode
    verticalComparison: ReactNode
}

/** Selects one stable comparison layout without observing diagram or edit-session state. */
export function DiagramComparisonLayout({
    horizontalComparison,
    layoutService = diagramComparisonLayoutService,
    tabbedComparison,
    verticalComparison,
}: DiagramComparisonLayoutProps) {
    const comparisonMode = useSyncExternalStore(
        layoutService.subscribeComparisonMode,
        layoutService.getComparisonModeSnapshot,
        layoutService.getComparisonModeSnapshot,
    )
    const handleModeChange = useCallback((_event: SyntheticEvent, mode: DiagramComparisonMode | null) => {
        if (!mode) return

        layoutService.setComparisonMode(mode)
    }, [layoutService])
    const comparisonByMode: Record<DiagramComparisonMode, ReactNode> = {
        horizontal: horizontalComparison,
        tabbed: tabbedComparison,
        vertical: verticalComparison,
    }

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', height: '100%', minHeight: 0, minWidth: 0, overflow: 'hidden' }}>
            <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 1, minWidth: 0, pb: 1 }}>
                <Typography color="text.secondary" sx={{ flexShrink: 0 }} variant="body2">Layout</Typography>
                <ToggleButtonGroup
                    aria-label="Diagram comparison layout"
                    exclusive
                    onChange={handleModeChange}
                    size="small"
                    sx={{
                        bgcolor: 'custom.track',
                        borderRadius: 1,
                        display: 'flex',
                        flex: 1,
                        minWidth: 0,
                        p: 0.375,
                        '& .MuiToggleButtonGroup-grouped': {
                            border: 0,
                            borderRadius: '6px !important',
                            flex: 1,
                            minWidth: 0,
                            px: 1,
                        },
                        '& .Mui-selected': { bgcolor: 'background.paper', color: 'primary.main' },
                    }}
                    value={comparisonMode}
                >
                    <ToggleButton value="vertical">Vertical</ToggleButton>
                    <ToggleButton value="horizontal">Horizontal</ToggleButton>
                    <ToggleButton value="tabbed">Tabbed</ToggleButton>
                </ToggleButtonGroup>
            </Box>
            <Box aria-label="Selected diagram comparison" sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto' }}>
                {comparisonByMode[comparisonMode]}
            </Box>
        </Box>
    )
}

